+fn swing_lines(world: &World) -> Vec<String> {
+    verification_gate(world)
+        .into_iter()
+        .filter(|p| p.contains("index turns the work") || p.contains("nose_to_axis") || p.contains("index swing"))
+        .collect()
+}
